455	fn render_card(card: &Card, width: usize, agent: &str) -> Vec<String> {
456	    let mut lines: Vec<String> = Vec::new();
457	    let w = width.saturating_sub(2);
458	
459	    match card {
460	        Card::RepoLink { name, dir, branch } => {
461	            let home = std::env::var("HOME").unwrap_or_default();
462	            let short = if !home.is_empty() && dir.starts_with(&home) {
463	                format!("~{}", &dir[home.len()..])
464	            } else { dir.clone() };
465	            let branch_part = if !branch.is_empty() {
466	                format!("  \x1b[38;5;220m[{branch}]\x1b[0m")
467	            } else { String::new() };
468	            lines.push(format!("\x1b[38;5;240m▸ repo  \x1b[0m\x1b[1;38;5;75m{name}\x1b[0m  \x1b[38;5;240m{short}\x1b[0m{branch_part}"));
469	        }
470	        Card::Header { title, cwd: _, branch: _, ts, agent: hdr_agent } => {
471	            let t = title.as_deref().unwrap_or("(untitled session)");
472	            let (agent_label, agent_col) = if hdr_agent.is_empty() {
473	                ("claude".to_string(), 75u8)
474	            } else {
475	                (hdr_agent.to_lowercase(), agent_color(hdr_agent))
476	            };
477	            let agent_part = format!("  \x1b[1;38;5;{agent_col}m{agent_label}\x1b[0m");
478	            let ts_part = if !ts.is_empty() {
479	                format!("  \x1b[38;5;240m{}\x1b[0m", rel_time(ts))
480	            } else { String::new() };
481	            lines.push(format!("\x1b[1;38;5;229m{t}\x1b[0m{agent_part}{ts_part}"));
482	        }
483	        Card::System { ts, subtype, content } => {
484	            lines.push(format!("\x1b[38;5;240m── {subtype}  {}\x1b[0m", rel_time(ts)));
485	            lines.push(String::new());
486	            for l in wrap(content, w) { lines.push(format!("  \x1b[38;5;240m{l}\x1b[0m")); }
487	        }
488	        Card::UserMsg { ts, parts } => {
489	            lines.push(format!("\x1b[1;38;5;82m── user  \x1b[0m\x1b[38;5;240m{}\x1b[0m", rel_time(ts)));
490	            for part in parts {
491	                match part {
492	                    UserPart::Text(text) => {
493	                        lines.push(String::new());
494	                        for l in render_md(text, w.saturating_sub(2)) { lines.push(format!("  {l}")); }
495	                    }
496	                    UserPart::ToolResult { name, content, is_error, .. } => {
497	                        let col = if *is_error { "38;5;196" } else { "38;5;177" };
498	                        lines.push(format!("\x1b[{col}m  ◀ {name}\x1b[0m"));
499	                        let visible: Vec<&str> = content.lines()
500	                            .filter(|l| !l.trim().is_empty()).take(8).collect();
501	                        for l in wrap(&visible.join("\n"), w.saturating_sub(4)) {
502	                            lines.push(format!("\x1b[38;5;240m    {l}\x1b[0m"));
503	                        }
504	                        let total = content.lines().filter(|l| !l.trim().is_empty()).count();
505	                        if total > 8 {
506	                            lines.push(format!("\x1b[38;5;238m    … {} more lines\x1b[0m", total - 8));
507	                        }
508	                    }
509	                }
510	            }
511	        }
512	        Card::AsstMsg { ts, parts } => {
513	            let (agent_label, agent_col) = if agent.is_empty() {
514	                ("claude".to_string(), 75u8)
515	            } else {
516	                (agent.to_lowercase(), agent_color(agent))
517	            };
518	            lines.push(format!("\x1b[1;38;5;{agent_col}m── {agent_label}  \x1b[0m\x1b[38;5;240m{}\x1b[0m", rel_time(ts)));
519	            for part in parts {
520	                if let AsstPart::Text(text) = part {
521	                    lines.push(String::new());
522	                    for l in render_md(text, w.saturating_sub(2)) { lines.push(format!("  {l}")); }
523	                }
524	            }
525	        }
526	        Card::ToolRound { .. } => {} // handled in build_flat
527	    }
528	
529	    lines.push(String::new());
530	    lines
531	}
