560	fn render_one_tool_call(part: &AsstPart, w: usize) -> Vec<String> {
561	    let mut lines = Vec::new();
562	    if let AsstPart::ToolCall { name, input, result, .. } = part {
563	        lines.push(format!("\x1b[38;5;220m  ▶ {name}\x1b[0m"));
564	        if let Some(obj) = input.as_object() {
