568	                let first_line = raw_val.lines().next().unwrap_or("");
569	                let preview: String = first_line.chars().take(120).collect();
570	                let suffix = if raw_val.lines().count() > 1 || first_line.chars().count() > 120 { " …" } else { "" };
571	                let col = if is_first { "38;5;255" } else { "38;5;245" };
572	                lines.push(format!("\x1b[{col}m    {preview}{suffix}\x1b[0m"));
573	                is_first = false;
574	            }
575	            if obj.len() > 4 {
576	                lines.push(format!("\x1b[38;5;238m    … {} more fields\x1b[0m", obj.len() - 4));
577	            }
578	        }
579	        if let Some((content, is_error)) = result {
580	            lines.push(format!("\x1b[38;5;238m  ────────────────────────────────────────\x1b[0m"));
581	            let col = if *is_error { "38;5;196" } else { "38;5;240" };
582	            let visible: Vec<&str> = content.lines()
583	                .filter(|l| !l.trim().is_empty()).take(8).collect();
584	            for l in wrap(&visible.join("\n"), w.saturating_sub(4)) {
585	                lines.push(format!("\x1b[{col}m    {l}\x1b[0m"));
586	            }
587	            let total = content.lines().filter(|l| !l.trim().is_empty()).count();
588	            if total > 8 {
589	                lines.push(format!("\x1b[38;5;238m    … {} more lines\x1b[0m", total - 8));
590	            }
591	        }
592	        lines.push(String::new());
593	    }
594	    lines
595	}
