803	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
804	/// so `claude --resume` can be run from the correct directory and branch is known.
805	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
806	    use std::io::BufRead;
807	    let home = std::env::var("HOME").ok()?;
808	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
809	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
810	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
811	        if !jsonl.exists() { continue; }
812	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
813	        let mut cwd = String::new();
814	        let mut branch = String::new();
815	        for line in std::io::BufReader::new(file).lines().flatten() {
816	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
817	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
818	                if cwd.is_empty() {
819	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
820	                }
821	                if branch.is_empty() {
822	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
823	                }
824	                if !cwd.is_empty() && !branch.is_empty() { break; }
825	            }
826	        }
827	        return Some((cwd, branch));
828	    }
829	    None
830	}
831	
832	fn do_resume(_agent: &str, session_id: &str, session_branch: &str, session_cwd: &str) {
833	    let current = git_current_branch(session_cwd);
834	    let same_branch = !session_branch.is_empty()
835	        && current.as_deref() == Some(session_branch);
836	
837	    let dir = if same_branch || session_branch.is_empty() {
838	        session_cwd.to_string()
839	    } else {
840	        create_resume_worktree(session_cwd, session_branch)
841	            .unwrap_or_else(|| session_cwd.to_string())
842	    };
843	
844	    resume_session(session_id, &dir);
845	}
846	
847	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
848	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
849	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
850	    use std::os::unix::process::CommandExt;
851	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
852	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
853	            fallback_cwd.to_string()
854	        } else {
855	            session_cwd
856	        };
857	        let err = std::process::Command::new("claude")
858	            .arg("--resume")
859	            .arg(session_id)
860	            .current_dir(&launch_dir)
861	            .exec();
862	        eprintln!("exec failed: {err}");
863	        // exec failed — fall back to entire resume, checking out the session branch first
864	        resume_via_entire(&launch_dir, &session_branch);
865	    } else {
866	        resume_via_entire(fallback_cwd, "");
867	    }
868	}
