871	
872	fn build_flat(
873	    cards: &[Card],
874	    term_w: usize,
875	    collapsed: &std::collections::HashSet<usize>,
876	) -> (Vec<(usize, String)>, Vec<Selectable>, Vec<usize>) {
877	    let w = term_w.saturating_sub(2);
878	    let mut flat: Vec<(usize, String)> = Vec::new();
879	    let mut selectables: Vec<Selectable> = Vec::new();
880	    let mut starts: Vec<usize> = Vec::new();
881	
882	    // Pull the agent name from the Header card so render_card can use it.
883	    let agent: &str = cards.iter().find_map(|c| {
884	        if let Card::Header { agent, .. } = c { Some(agent.as_str()) } else { None }
885	    }).unwrap_or("");
886	
887	    for (card_idx, card) in cards.iter().enumerate() {
888	        if let Card::ToolRound { parts } = card {
889	            if collapsed.contains(&card_idx) {
890	                let si = selectables.len();
891	                starts.push(flat.len());
892	                selectables.push(Selectable::Card(card_idx));
893	                for l in render_tool_summary(parts) { flat.push((si, l)); }
894	            } else {
895	                // Header row (collapses the round when space is pressed)
896	                let si = selectables.len();
897	                starts.push(flat.len());
898	                selectables.push(Selectable::ToolHeader(card_idx));
899	                for l in render_tool_header(parts) { flat.push((si, l)); }
900	                // One selectable per individual tool call
901	                for (tool_idx, part) in parts.iter().enumerate() {
902	                    let si = selectables.len();
903	                    starts.push(flat.len());
904	                    selectables.push(Selectable::ToolCall(card_idx, tool_idx));
905	                    for l in render_one_tool_call(part, w) { flat.push((si, l)); }
906	                }
907	            }
908	        } else {
909	            let si = selectables.len();
910	            starts.push(flat.len());
911	            selectables.push(Selectable::Card(card_idx));
912	            for l in render_card(card, w, agent) { flat.push((si, l)); }
913	        }
914	    }
915	
916	    (flat, selectables, starts)
917	}
918	
919	enum PagerOutcome { Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
920	
921	fn pager(cards: &[Card], start_ts: Option<&str>) -> Result<PagerOutcome> {
922	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
923	    let mut w = term_w as usize;
924	    let mut h = (term_h as usize).saturating_sub(1);
925	
926	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
927	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. }) { Some(i) } else { None })
928	        .collect();
929	
930	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed);
931	
932	    let mut stdout = io::stdout();
933	
934	    let orig_hook = std::panic::take_hook();
935	    std::panic::set_hook(Box::new(move |info| {
936	        let mut out = io::stdout();
937	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
938	        let _ = terminal::disable_raw_mode();
939	        orig_hook(info);
940	    }));
941	
942	    terminal::enable_raw_mode()?;
943	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
944	
945	    // If a target timestamp was given, jump to the first card whose ts matches.
946	    // Otherwise land on the first non-navigation card (skip RepoLink and Header).
947	    let initial_sel = start_ts.and_then(|ts| {
948	        cards.iter().enumerate().find_map(|(ci, card)| {
949	            let card_ts = match card {
950	                Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
951	                _ => return None,
952	            };
953	            if card_ts == ts {
954	                selectables.iter().position(|s| *s == Selectable::Card(ci))
955	            } else {
956	                None
957	            }
958	        })
959	    }).unwrap_or_else(|| selectables.len().saturating_sub(1));
960	
961	    let mut sel: usize = initial_sel;
962	    let mut scroll: usize = 0;
963	    let mut flash:  Option<&str> = None;
964	    let mut awaiting_delete = false;
965	
966	    let result: Result<PagerOutcome> = loop {
967	        let s = starts[sel];
968	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
969	        if s < scroll          { scroll = s; }
970	        else if e > scroll + h { scroll = e.saturating_sub(h); }
971	
972	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
973	            break Err(anyhow::anyhow!(err));
974	        }
975	
976	        match event::read() {
977	            Err(e) => break Err(e.into()),
978	            Ok(Event::Key(k)) => {
979	                let prev_flash = flash.take();
980	                match (k.code, k.modifiers) {
981	                    (KeyCode::Char('q') | KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Quit),
982	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
983	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
984	                    (KeyCode::Char('d'), _) => {
985	                        awaiting_delete = true;
986	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
987	                        continue;
988	                    }
989	                    (KeyCode::Char('y'), _) if awaiting_delete => {
990	                        break Ok(PagerOutcome::Delete);
991	                    }
992	
993	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
994	                        if sel + 1 < selectables.len() { sel += 1; }
995	                    }
996	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
997	                        if sel > 0 { sel -= 1; }
998	                    }
999	                    (KeyCode::Char('g'), _) => { sel = 0; }
1000	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1001	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1002	                        scroll = scroll.saturating_sub(h / 2);
1003	                        sel = flat[scroll].0;
1004	                    }
1005	                    (KeyCode::PageDown, _) => {
1006	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1007	                        sel = flat[scroll].0;
1008	                    }
1009	
1010	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1011	                        let text = match &selectables[sel] {
1012	                            Selectable::Card(ci)         => card_text(&cards[*ci]),
1013	                            Selectable::ToolHeader(ci)   => card_text(&cards[*ci]),
1014	                            Selectable::ToolCall(ci, ti) => {
1015	                                if let Card::ToolRound { parts } = &cards[*ci] {
1016	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1017	                                } else { String::new() }
1018	                            }
1019	                        };
1020	                        copy_to_clipboard(&text);
1021	                        flash = Some("  ✓ copied to clipboard  ");
1022	                    }
1023	
1024	                    // Space/Right/Enter: expand ToolRound, collapse via header, or navigate
1025	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1026	                        let expand_action = match &selectables[sel] {
1027	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1028	                                Some((true, *ci))
1029	                            }
1030	                            Selectable::ToolHeader(ci) => Some((false, *ci)),
1031	                            _ => None,
1032	                        };
1033	                        if let Some((expand, card_idx)) = expand_action {
1034	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1035	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed);
1036	                            flat   = nf;
1037	                            starts = nst;
1038	                            sel = if expand {
1039	                                ns.iter().position(|s| *s == Selectable::ToolHeader(card_idx))
1040	                            } else {
1041	                                ns.iter().position(|s| *s == Selectable::Card(card_idx))
1042	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1043	                            selectables = ns;
1044	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1045	                            match &cards[*ci] {
1046	                                Card::RepoLink { dir, .. } => {
1047	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1048	                                }
1049	                                Card::Header { .. } => {
1050	                                    break Ok(PagerOutcome::GoToSessions);
1051	                                }
1052	                                _ => { flash = prev_flash; }
1053	                            }
1054	                        } else {
1055	                            flash = prev_flash;
1056	                        }
1057	                    }
1058	
1059	                    _ => { awaiting_delete = false; flash = prev_flash; }
1060	                }
1061	            }
1062	            Ok(Event::Resize(new_w, new_h)) => {
1063	                w = new_w as usize;
1064	                h = (new_h as usize).saturating_sub(1);
1065	                let (nf, ns, nst) = build_flat(&cards, w, &collapsed);
1066	                flat = nf; selectables = ns; starts = nst;
1067	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
1068	            }
1069	            Ok(_) => {}
1070	        }
1071	    };
1072	
1073	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1074	    terminal::disable_raw_mode()?;
1075	    result
1076	}
1077	
1078	fn draw(
1079	    stdout: &mut impl Write,
1080	    flat:   &[(usize, String)],
1081	    starts: &[usize],
1082	    sel:    usize,
1083	    scroll: usize,
1084	    h:      usize,
1085	    w:      usize,
1086	    total:  usize,
1087	    flash:  Option<&str>,
1088	) -> io::Result<()> {
1089	    use crossterm::queue;
1090	    const SEL_BG: &str = "48;5;236";
1091	
1092	    let end = (scroll + h).min(flat.len());
1093	
1094	    // Build the entire frame into one buffer; flush once to eliminate flicker.
1095	    // Use explicit cursor::MoveTo per row so embedded newlines in content can't
1096	    // shift subsequent rows into the wrong position.
1097	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
1098	
1099	    for row in 0..h {
1100	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
1101	
1102	        let flat_idx = scroll + row;
1103	        if flat_idx < end {
1104	            let (card_idx, line) = &flat[flat_idx];
1105	            if *card_idx == sel {
1106	                let line_bg = with_bg(line, SEL_BG);
1107	                let vis = visible_width(line);
1108	                let pad = w.saturating_sub(vis);
1109	                write!(buf, "\x1b[{SEL_BG}m{line_bg}{}\x1b[0m", " ".repeat(pad))?;
1110	            } else {
1111	                buf.extend_from_slice(line.as_bytes());
1112	            }
1113	        }
1114	    }
1115	
1116	    // Status bar
1117	    let sel_end = starts.get(sel + 1).copied().unwrap_or(flat.len());
1118	    let base = format!(
1119	        "  {}/{} msgs  lines {}-{}  j/k ↑↓ navigate  u/PgDn page  g/G ends  y/c copy  r resume  d delete  q quit  ",
1120	        sel + 1, total, starts[sel] + 1, sel_end,
1121	    );
1122	    let bar = if let Some(msg) = flash {
1123	        let skip = msg.chars().count();
1124	        let rest: String = base.chars().skip(skip).collect();
1125	        format!("{msg}{rest}")
1126	    } else {
1127	        base
1128	    };
1129	    let bar_display: String = bar.chars().take(w).collect();
1130	    let padded = format!("{bar_display:width$}", width = w);
1131	    queue!(buf, cursor::MoveTo(0, h as u16))?;
1132	    write!(buf, "\x1b[7m{padded}\x1b[0m")?;
1133	
1134	    stdout.write_all(&buf)?;
1135	    stdout.flush()
1136	}
