978	fn visible_width(s: &str) -> usize {
979	    let mut w = 0usize;
980	    let mut chars = s.chars().peekable();
981	    while let Some(c) = chars.next() {
982	        if c == '\x1b' {
983	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
984	        } else {
985	            w += 1;
986	        }
987	    }
988	    w
989	}
