991	fn relative_time(dt: DateTime<Utc>) -> String {
992	    let secs = (Utc::now() - dt).num_seconds().max(0);
993	    if secs < 604_800 {
994	        match secs {
995	            s if s < 60     => "just now".to_string(),
996	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
997	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
998	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
999	        }
1000	    } else {
1001	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
1002	    }
1003	}
