1005	pub fn run_for_dir(repo_dir: &str) -> Result<()> {
1006	    let conn = db::connect()?;
1007	    let repos = fetch_repos(&conn)?;
1008	    let start = repos.iter().position(|r| r.directory == repo_dir);
1009	
1010	    let orig_hook = std::panic::take_hook();
1011	    std::panic::set_hook(Box::new(move |info| {
1012	        let mut out = io::stdout();
1013	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1014	        let _ = terminal::disable_raw_mode();
1015	        orig_hook(info);
1016	    }));
1017	
1018	    let mut stdout = io::stdout();
1019	    terminal::enable_raw_mode()?;
1020	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1021	
1022	    let outcome = tui_loop(&mut stdout, &repos, false, start);
1023	
1024	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1025	    terminal::disable_raw_mode()?;
1026	
1027	    match outcome? {
1028	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
1029	            super::show::resume_session(&id, &cwd);
1030	        }
1031	        Some(TuiOutcome::LaunchAgent { cli, cwd, session_name, prompt }) => {
1032	            use std::os::unix::process::CommandExt;
1033	            let mut cmd = std::process::Command::new(&cli);
1034	            if !cwd.is_empty() { cmd.current_dir(&cwd); }
1035	            if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
1036	            if !prompt.is_empty() { cmd.arg(&prompt); }
1037	            let err = cmd.exec();
1038	            eprintln!("Failed to launch {cli}: {err}");
1039	        }
1040	        _ => {}
1041	    }
1042	
1043	    Ok(())
1044	}
