1046	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
1047	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
1048	    let repos = stmt.query_map([], |row| {
1049	        Ok(Repository {
1050	            id: row.get(0)?,
1051	            directory: row.get(1)?,
1052	            remote: row.get(2)?,
1053	            name: row.get(3)?,
1054	        })
